INSERT INTO social.broadcast_notifications AS t (id, type, metadata, occurred_at, created_at)
SELECT id, type, metadata, occurred_at AT TIME ZONE 'UTC', created_at AT TIME ZONE 'UTC'
FROM stage
ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, metadata = EXCLUDED.metadata,
    occurred_at = EXCLUDED.occurred_at;

-- Convert only copies carrying both identifiers generated by the former loader.
-- Preserve reads made on the node before removing those duplicate inbox entries.
INSERT INTO social.broadcast_reads AS t (broadcast_id, address, read_at)
SELECT s.id, n.address, COALESCE(n.read_at, n.occurred_at)
FROM stage s JOIN social.notifications n
  ON n.broadcast_key = 'notifications-workers:' || s.id::text
 AND n.id = md5(s.id::text || ':' || n.address)::uuid
WHERE n.read
ON CONFLICT (broadcast_id, address) DO UPDATE SET read_at = LEAST(t.read_at, EXCLUDED.read_at);

DELETE FROM social.notifications n USING stage s
WHERE n.broadcast_key = 'notifications-workers:' || s.id::text
  AND n.id = md5(s.id::text || ':' || n.address)::uuid;
